import React, { useState } from 'react';

const QuanLyThongBaoCuDan = () => {
    // 3 mục: 'xem' (Xem thông báo), 'admin' (Gửi Admin), 'nhom' (Gửi nhóm chung)
    const [activeTab, setActiveTab] = useState('xem');

    return (
        <div style={styles.container}>
            {/* 1. Lớp nền ảnh mờ tòa nhà */}
            <div style={styles.backgroundBlur} />

            {/* 2. Nội dung chính bọc trong Thẻ (Card) trắng */}
            <div style={styles.contentCard} className="fade-in modern-card">
                <header style={styles.header}>
                    <h2 style={styles.mainTitle}>🔔 Trung Tâm Thông Báo & Kết Nối</h2>
                    <div style={styles.tabBar}>
                        <button 
                            onClick={() => setActiveTab('xem')} 
                            style={{...styles.tabBtn, backgroundColor: activeTab === 'xem' ? '#2e7d32' : 'transparent', color: activeTab === 'xem' ? '#fff' : '#718096'}}
                        >
                            📢 Xem thông báo
                        </button>
                        <button 
                            onClick={() => setActiveTab('admin')} 
                            style={{...styles.tabBtn, backgroundColor: activeTab === 'admin' ? '#1976d2' : 'transparent', color: activeTab === 'admin' ? '#fff' : '#718096'}}
                        >
                            👨‍💼 Gửi Admin
                        </button>
                        <button 
                            onClick={() => setActiveTab('nhom')} 
                            style={{...styles.tabBtn, backgroundColor: activeTab === 'nhom' ? '#ed6c02' : 'transparent', color: activeTab === 'nhom' ? '#fff' : '#718096'}}
                        >
                            👥 Nhóm chung
                        </button>
                    </div>
                </header>

                <div style={styles.tabContent}>
                    {/* 1. XEM THÔNG BÁO (Từ Ban Quản Lý) */}
                    {activeTab === 'xem' && (
                        <div className="fade-in">
                            <h3 style={{color: '#2e7d32', marginBottom: '20px', fontSize: '18px'}}>Thông báo từ tòa nhà</h3>
                            <div style={styles.newsItem}>
                                <div style={styles.postHeader}>
                                    <span style={styles.badgeMoi}>MỚI</span>
                                    <span style={styles.timeLabel}>17/04/2026</span>
                                </div>
                                <h4 style={{margin: '10px 0', color: '#2d3748'}}>Thông báo bảo trì thang máy tòa A</h4>
                                <p style={styles.postContent}>Thang máy số 3 tòa A sẽ tạm dừng hoạt động để bảo trì định kỳ từ 14h-16h chiều nay. Mong cư dân thông cảm...</p>
                                <button style={styles.btnDetail}>Xem chi tiết nội dung</button>
                            </div>
                        </div>
                    )}

                    {/* 2. GỬI ADMIN (Phản hồi/Yêu cầu hỗ trợ) */}
                    {activeTab === 'admin' && (
                        <div className="fade-in">
                            <h3 style={{color: '#1976d2', marginBottom: '25px', fontSize: '18px'}}>Gửi yêu cầu tới Ban Quản Lý</h3>
                            <input type="text" placeholder="Chủ đề phản hồi (VD: Báo hỏng, Vệ sinh...)" style={{...styles.input, borderColor: '#1976d2', borderLeft: '4px solid #1976d2'}} />
                            <textarea placeholder="Nội dung chi tiết cư dân cần hỗ trợ..." style={styles.textarea} />
                            <button style={{...styles.submitBtn, backgroundColor: '#1976d2', boxShadow: '0 4px 12px rgba(25, 118, 210, 0.2)'}}>📩 Gửi phản hồi ngay</button>
                        </div>
                    )}

                    {/* 3. NHÓM CHUNG (Chia sẻ cộng đồng) */}
                    {activeTab === 'nhom' && (
                        <div className="fade-in">
                            <h3 style={{color: '#ed6c02', marginBottom: '25px', fontSize: '18px'}}>Chia sẻ với cộng đồng cư dân</h3>
                            <textarea 
                                placeholder="Nội dung chia sẻ (VD: Tìm đồ lạc, rủ mua chung...)" 
                                style={{...styles.textarea, borderColor: '#ed6c02', borderLeft: '4px solid #ed6c02'}}
                            />
                            <button style={{...styles.submitBtn, backgroundColor: '#ed6c02', boxShadow: '0 4px 12px rgba(237, 108, 2, 0.2)'}}>🚀 Đăng lên bảng tin chung</button>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

const styles = {
    // Container chính với nền xám nhạt
    container: { 
        position: 'relative',
        minHeight: '100vh',
        backgroundColor: '#f4f6f8',
        fontFamily: "'Inter', sans-serif"
    },
    // Hiệu ứng nền tòa nhà mờ
    backgroundBlur: {
        position: 'fixed',
        top: 0, left: 0, right: 0, bottom: 0,
        backgroundImage: `linear-gradient(rgba(244, 246, 248, 0.8), rgba(244, 246, 248, 0.8)), url('https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?q=80&w=2070')`,
        backgroundSize: 'cover',
        backgroundPosition: 'center',
        filter: 'blur(20px)', // Làm mờ mạnh
        opacity: 0.1, // Độ trong suốt cực thấp
        zIndex: -1 // Đẩy ra sau cùng
    },
    // Thẻ nội dung trắng tinh khôi
    contentCard: {
        maxWidth: '1000px',
        margin: '30px auto',
        backgroundColor: '#ffffff',
        borderRadius: '20px',
        padding: '40px',
        boxShadow: '0 15px 35px rgba(0,0,0,0.05)'
    },
    header: { textAlign: 'center', marginBottom: '40px' },
    mainTitle: { fontSize: '26px', fontWeight: 'bold', color: '#1a202c', marginBottom: '20px' },
    tabBar: { display: 'inline-flex', gap: '5px', backgroundColor: '#edf2f7', padding: '5px', borderRadius: '12px' },
    tabBtn: { padding: '12px 24px', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600', transition: '0.3s', fontSize: '14px' },
    tabContent: { marginTop: '10px' },
    input: { width: '100%', padding: '16px', marginBottom: '15px', borderRadius: '12px', border: '1px solid #e2e8f0', backgroundColor: '#f8fafc', boxSizing: 'border-box', outline: 'none' },
    textarea: { width: '100%', padding: '16px', height: '160px', marginBottom: '20px', borderRadius: '12px', border: '1px solid #e2e8f0', backgroundColor: '#f8fafc', resize: 'none', boxSizing: 'border-box', outline: 'none' },
    submitBtn: { width: '100%', padding: '16px', color: '#fff', border: 'none', borderRadius: '12px', fontWeight: 'bold', fontSize: '16px', cursor: 'pointer', transition: '0.2s' },
    newsItem: { border: '1px solid #edf2f7', padding: '24px', borderRadius: '18px', marginBottom: '15px', backgroundColor: '#fff', borderLeft: '6px solid #2e7d32' },
    postHeader: { display: 'flex', justifyContent: 'space-between', alignItems: 'center' },
    badgeMoi: { backgroundColor: '#fed7d7', color: '#c53030', padding: '5px 12px', borderRadius: '6px', fontSize: '11px', fontWeight: 'bold' },
    timeLabel: { color: '#a0aec0', fontSize: '12px' },
    postContent: { color: '#4a5568', lineHeight: '1.6', fontSize: '14px', marginTop: '10px' },
    btnDetail: { background: 'none', border: 'none', color: '#2e7d32', fontWeight: 'bold', cursor: 'pointer', marginTop: '12px', padding: 0, fontSize: '13px', textDecoration: 'underline' }
};

export default QuanLyThongBaoCuDan;
